import { mkdir, writeFile } from "node:fs/promises";

const result = await Bun.build({
  entrypoints: ["./src/lib/case-edge.server.ts"],
  target: "browser",
  format: "esm",
  env: "disable",
  minify: true,
  sourcemap: "none",
  banner:
    "// Generated by scripts/build-edge.ts. Server deployment only; never serve as a browser asset.",
});
if (!result.success || result.outputs.length !== 1) throw new Error("Edge bundle failed");
await mkdir("supabase/functions/_shared", { recursive: true });
await writeFile("supabase/functions/_shared/case-api.js", await result.outputs[0]!.text());
console.log("Built Supabase case-api bundle with environment injection disabled.");
